package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import java.io.*;
import java.nio.ByteBuffer;
import java.util.*;

/** Bounded source preparation and exact cancellation, independent from ordinary proof dependencies. */
public final class RatisSourceOutcomeRpc {
    public static final int PREPARE=98,CANCEL=99;
    public static final int MAX_REQUEST_BYTES=ScopedTransactionRpc.HEADER_BYTES+16+RatisSourceOutcomeRecord.MAX_BYTES+NativeSourceOutcomeCredit.Request.MAX_BYTES+(int)RatisTransactionPlan.MAX_BYTES+36*TransactionStatus.MAX_PARTICIPANTS;
    public static final int MAX_REPLY_BYTES=ScopedTransactionRpc.HEADER_BYTES+37+RatisSourceOutcomeRecord.MAX_BYTES;
    private RatisSourceOutcomeRpc(){}
    public record Proposal(RatisSourceOutcomeRecord.Kind kind,NativeSourceOutcomeCredit.Request request,List<RatisDurableTransaction.Intent> intents,RatisSourceOutcomeRecord frozenRecord){public Proposal(RatisSourceOutcomeRecord.Kind kind,NativeSourceOutcomeCredit.Request request,List<RatisDurableTransaction.Intent> intents){this(kind,request,intents,null);}public Proposal{Objects.requireNonNull(kind);Objects.requireNonNull(request);intents=intents.stream().sorted(Comparator.comparing(i->i.route().groupId())).toList();if(intents.size()>TransactionStatus.MAX_PARTICIPANTS || kind==RatisSourceOutcomeRecord.Kind.CREDIT && !intents.isEmpty())throw new IllegalArgumentException("Invalid source proof count");if(frozenRecord!=null && (frozenRecord.kind()!=kind || !frozenRecord.request().equals(request)))throw new IllegalArgumentException("Frozen source record changed input");}}
    public record Prepared(byte[] requestDigest,RatisSourceOutcomeRecord record,boolean fenced){public Prepared{if(requestDigest.length!=32 || fenced!=(record==null))throw new IllegalArgumentException("Invalid source preparation result");requestDigest=requestDigest.clone();if(record!=null && !Arrays.equals(requestDigest,record.request().digest()))throw new IllegalArgumentException("Source preparation request changed");}@Override public byte[] requestDigest(){return requestDigest.clone();}}
    public record Applied(byte[] recordDigest,NativeSourceOutcomePublication.Outcome outcome,byte[] proof){public Applied{if(recordDigest.length!=32)throw new IllegalArgumentException("Invalid source apply binding");Objects.requireNonNull(outcome);if(outcome==NativeSourceOutcomePublication.Outcome.CLOSED && proof!=null)throw new IllegalArgumentException("Closed source carries no fresh authority");recordDigest=recordDigest.clone();proof=proof==null?null:proof.clone();}@Override public byte[] recordDigest(){return recordDigest.clone();}@Override public byte[] proof(){return proof==null?null:proof.clone();}}
    public static boolean kind(int kind){return kind==PREPARE || kind==CANCEL;}
    public static byte[] prepare(Proposal proposal){
        try{var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeInt(proposal.kind().ordinal());put(out,proposal.request().encode());out.writeInt(proposal.intents().size());long aggregate=0;
            var plan=proposal.intents().isEmpty()?null:RatisTransactionPlan.fromOriginal(proposal.request().targetDirectory(),proposal.request().original());
            int n=0;if(plan!=null)for(var partition:plan.partitions()){var intent=proposal.intents().stream().filter(i->i.route().groupId().equals(partition.route().groupId())).findFirst().orElseThrow(()->new IllegalArgumentException("Missing source intent"));if(!intent.route().equals(partition.route()) || !intent.resultPositions().equals(partition.resultPositions()) || !intent.prepareControl().equals(control(proposal.request(),n)) || !intent.finalizeControl().equals(control(proposal.request(),64+n++)) || intent.captureId()==null)throw new IllegalArgumentException("Source intent changed derived capture projection");}
            for(var intent:proposal.intents()){byte[] command=DistributedCommandCodec.encode(intent.acceptedBusiness());aggregate+=command.length;if(aggregate>RatisTransactionPlan.MAX_BYTES)throw new IllegalArgumentException("Source accepted aggregate exceeds bound");uuid(out,intent.route().groupId());uuid(out,Objects.requireNonNull(intent.captureId()));put(out,command);}put(out,proposal.frozenRecord()==null?new byte[0]:proposal.frozenRecord().encode());out.flush();if(bytes.size()>MAX_REQUEST_BYTES-ScopedTransactionRpc.HEADER_BYTES)throw new IllegalArgumentException("Source request exceeds bound");return ScopedTransactionRpc.frame(PREPARE,bytes.toByteArray());
        }catch(IOException impossible){throw new AssertionError(impossible);}
    }
    public static Proposal proposal(byte[] bytes){int kind=ScopedTransactionRpc.kind(bytes,MAX_REQUEST_BYTES);if(kind!=PREPARE && kind!=CANCEL)throw new IllegalArgumentException("Wrong source prepare kind");var in=ByteBuffer.wrap(bytes,ScopedTransactionRpc.HEADER_BYTES,bytes.length-ScopedTransactionRpc.HEADER_BYTES);if(in.remaining()<4)throw new IllegalArgumentException("Truncated source kind");int tag=in.getInt();if(tag<0 || tag>=RatisSourceOutcomeRecord.Kind.values().length)throw new IllegalArgumentException("Invalid source preparation tag");var request=NativeSourceOutcomeCredit.Request.decode(RatisSourceOutcomeRecord.blob(in,NativeSourceOutcomeCredit.Request.MAX_BYTES,false));if(in.remaining()<4)throw new IllegalArgumentException("Truncated source proof count");int count=in.getInt();if(count<0 || count>TransactionStatus.MAX_PARTICIPANTS || (tag==0 || kind==CANCEL) && count!=0)throw new IllegalArgumentException("Invalid source proof count");var accepted=new HashMap<UUID,DistributedCommand>();var captures=new HashMap<UUID,UUID>();long aggregate=0;
        for(int i=0;i<count;i++){if(in.remaining()<32)throw new IllegalArgumentException("Truncated source capture");UUID group=ScopedTransactionRpc.uuid(in),capture=ScopedTransactionRpc.uuid(in);byte[] command=RatisSourceOutcomeRecord.blob(in,DistributedCommandCodec.MAX_ENCODED_BYTES,false);aggregate+=command.length;if(aggregate>RatisTransactionPlan.MAX_BYTES || captures.putIfAbsent(group,capture)!=null)throw new IllegalArgumentException("Duplicate/oversized source capture");accepted.put(group,DistributedCommandCodec.decode(command));}byte[] frozen=RatisSourceOutcomeRecord.blob(in,RatisSourceOutcomeRecord.MAX_BYTES,false);if(in.hasRemaining() || kind==CANCEL && frozen.length!=0)throw new IllegalArgumentException("Trailing source preparation");var intents=new ArrayList<RatisDurableTransaction.Intent>();if(count>0){var plan=RatisTransactionPlan.fromOriginal(request.targetDirectory(),request.original());int n=0;for(var partition:plan.partitions()){UUID group=partition.route().groupId();var command=accepted.get(group);if(command==null)throw new IllegalArgumentException("Missing accepted source participant");intents.add(new RatisDurableTransaction.Intent(partition.route(),command,control(request,n),control(request,64+n++),partition.resultPositions(),captures.get(group)));}if(intents.size()!=count)throw new IllegalArgumentException("Foreign source participant");}return new Proposal(RatisSourceOutcomeRecord.Kind.values()[tag],request,intents,frozen.length==0?null:RatisSourceOutcomeRecord.decode(frozen));
    }
    public static byte[] cancel(RatisSourceOutcomeRecord record){return cancel(record.kind(),record.request());}
    public static byte[] cancel(RatisSourceOutcomeRecord.Kind kind,NativeSourceOutcomeCredit.Request request){byte[] body=ByteBuffer.allocate(16+request.encode().length).putInt(kind.ordinal()).putInt(request.encode().length).put(request.encode()).putInt(0).putInt(0).array();return ScopedTransactionRpc.frame(CANCEL,body);}
    public static byte[] cancelled(Proposal proposal){return ScopedTransactionRpc.frame(CANCEL,ByteBuffer.allocate(36).putInt(proposal.kind().ordinal()).put(proposal.request().digest()).array());}
    public static void requireCancelled(byte[] bytes,RatisSourceOutcomeRecord.Kind kind,NativeSourceOutcomeCredit.Request request){var packet=ScopedTransactionRpc.parse(bytes,ScopedTransactionRpc.HEADER_BYTES+36);var in=ByteBuffer.wrap(packet.body());byte[] digest=new byte[32];if(packet.kind()!=CANCEL || in.remaining()!=36 || in.getInt()!=kind.ordinal())throw new IllegalArgumentException("Invalid source cancellation reply");in.get(digest);if(!Arrays.equals(digest,request.digest()))throw new IllegalArgumentException("Source cancellation changed request");}
    public static byte[] prepared(Prepared prepared){byte[] record=prepared.record()==null?new byte[0]:prepared.record().encode();return ScopedTransactionRpc.frame(PREPARE,ByteBuffer.allocate(37+record.length).put(prepared.requestDigest()).put((byte)(prepared.fenced()?1:0)).putInt(record.length).put(record).array());}
    public static Prepared prepared(byte[] bytes,Proposal expected){if(ScopedTransactionRpc.kind(bytes,MAX_REPLY_BYTES)!=PREPARE)throw new IllegalArgumentException("Wrong source prepared reply");var in=ByteBuffer.wrap(bytes,ScopedTransactionRpc.HEADER_BYTES,bytes.length-ScopedTransactionRpc.HEADER_BYTES);if(in.remaining()<37)throw new IllegalArgumentException("Truncated source prepared reply");byte[] digest=new byte[32];in.get(digest);int fenced=in.get()&255;if(fenced>1)throw new IllegalArgumentException("Invalid source fence flag");byte[] record=RatisSourceOutcomeRecord.blob(in,RatisSourceOutcomeRecord.MAX_BYTES,false);if(in.hasRemaining() || !Arrays.equals(digest,expected.request().digest()))throw new IllegalArgumentException("Source prepared reply changed request");var prepared=new Prepared(digest,record.length==0?null:RatisSourceOutcomeRecord.decode(record),fenced==1);if(prepared.record()!=null && (prepared.record().kind()!=expected.kind() || !prepared.record().request().equals(expected.request()) || expected.frozenRecord()!=null && !prepared.record().equals(expected.frozenRecord())))throw new IllegalArgumentException("Source prepared kind changed");return prepared;}
    public static byte[] applied(RatisSourceOutcomeRecord record,NativeSourceOutcomePublication.Outcome outcome,byte[] proof){return ByteBuffer.allocate(37+(proof==null?0:proof.length)).put(record.digest()).put((byte)outcome.ordinal()).putInt(proof==null?0:proof.length).put(proof==null?new byte[0]:proof).array();}
    public static Applied applied(byte[] bytes,RatisSourceOutcomeRecord expected){if(bytes.length<37 || bytes.length>37+NativeSourceOutcomeCredit.MAX_BYTES)throw new IllegalArgumentException("Invalid source applied bound");var in=ByteBuffer.wrap(bytes);byte[] digest=new byte[32];in.get(digest);int outcome=in.get()&255;if(outcome>=NativeSourceOutcomePublication.Outcome.values().length)throw new IllegalArgumentException("Invalid source applied outcome");byte[] proof=RatisSourceOutcomeRecord.blob(in,NativeSourceOutcomeCredit.MAX_BYTES,false);if(in.hasRemaining() || !Arrays.equals(digest,expected.digest()))throw new IllegalArgumentException("Source applied reply changed record");if(outcome==NativeSourceOutcomePublication.Outcome.CLOSED.ordinal() && proof.length!=0)throw new IllegalArgumentException("Closed source carries no new outcome authority");if(outcome==NativeSourceOutcomePublication.Outcome.RETAINED.ordinal() && proof.length==0)throw new IllegalArgumentException("Retained source outcome requires native proof");if(proof.length>0){if(expected.kind()==RatisSourceOutcomeRecord.Kind.CREDIT){var credit=NativeSourceOutcomeCredit.decode(proof);if(!credit.request().equals(expected.request()))throw new IllegalArgumentException("Source credit changed input");}else {var publication=NativeSourceOutcomePublication.decode(proof);publication.requireRequest(expected.request(),expected.result());if(outcome==NativeSourceOutcomePublication.Outcome.RETAINED.ordinal() && publication.outcome()!=NativeSourceOutcomePublication.Outcome.RETAINED)throw new IllegalArgumentException("Retained source publication carries fenced proof");}}return new Applied(digest,NativeSourceOutcomePublication.Outcome.values()[outcome],proof.length==0?null:proof);}
    static OperationId control(NativeSourceOutcomeCredit.Request request,int offset){var first=request.origin().firstControl();return new OperationId(first.sessionId(),first.epoch(),first.sequence()+offset);}
    private static void put(DataOutputStream out,byte[] bytes)throws IOException{out.writeInt(bytes.length);out.write(bytes);}
    private static void uuid(DataOutputStream out,UUID id)throws IOException{out.writeLong(id.getMostSignificantBits());out.writeLong(id.getLeastSignificantBits());}
}
